/**
 * @event
 * @name scwin.krxpage_pagenavigator_74_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_74_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; scwin.goPage(); };
